import React, { useState, useEffect } from 'react';
import { Button, Form, Container } from 'react-bootstrap';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const AuthForm = ({ setUser }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('user');
  const [isLogin, setIsLogin] = useState(true);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname || '/';

  useEffect(() => {
    setEmail('');
    setPassword('');
    setError('');
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
  
    try {
      if (isLogin) {
        // 🔹 Login API request
        const response = await axios.post('http://localhost:8000/api/auth/login', {
          email,
          password,
        });
  
        console.log("🔹 Login Response:", response.data);
  
        if (response.data.token) {
          // ✅ Store token and role
          localStorage.setItem('authToken', response.data.token); 
          localStorage.setItem('role', response.data.role);
  
          // Update user state
          setUser({ email, role: response.data.role });
  
          // Redirect based on user role
          if (response.data.role === 'admin') {
            navigate('/admin-dashboard');
          } else {
            navigate(from, { replace: true });
          }
        } else {
          setError("Login failed: Token missing in response.");
        }
      } else {
        // 🔹 Signup API request
        const response = await axios.post('http://localhost:8000/api/auth/signup', {
          email,
          password,
          role,
        });
  
        alert(response.data.message || "Signup successful. Please log in.");
        setIsLogin(true); // Switch to login mode after signup
      }
    } catch (error) {
      console.error("❌ Auth Error:", error.response?.data || error.message);
      setError(error.response?.data?.message || "Something went wrong.");
    } finally {
      setLoading(false);
    }
  };
  

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setEmail('');
    setPassword('');
    setError('');
  };

  return (
    <Container className="mt-4 auth-form-container">
      <h2 className="text-center">{isLogin ? 'Login' : 'Signup'}</h2>
      {error && <p className="text-danger text-center">{error}</p>}
      <Form onSubmit={handleSubmit} autoComplete="off">
        <Form.Group controlId="formBasicEmail" className="form-group">
          <Form.Label>Email address</Form.Label>
          <Form.Control
            type="email"
            placeholder="Enter email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            name="email"
            autoComplete="new-email"
          />
        </Form.Group>

        <Form.Group controlId="formBasicPassword" className="form-group">
          <Form.Label>Password</Form.Label>
          <Form.Control
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            name="password"
            autoComplete="new-password"
          />
        </Form.Group>

        {!isLogin && (
          <Form.Group controlId="formBasicRole" className="form-group">
            <Form.Label>Role</Form.Label>
            <Form.Control
              as="select"
              value={role}
              onChange={(e) => setRole(e.target.value)}
              required
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </Form.Control>
          </Form.Group>
        )}

        <Button variant="primary" type="submit" className="mt-3" disabled={loading}>
          {loading ? 'Processing...' : isLogin ? 'Login' : 'Signup'}
        </Button>
      </Form>
      <Button variant="link" onClick={toggleMode} className="mt-3">
        {isLogin ? 'Switch to Signup' : 'Switch to Login'}
      </Button>
    </Container>
  );
};

export default AuthForm;
